+server_tokens tokenize_prompt_parts_with_input_escaping(
+    const llama_vocab * vocab,
+    const json & prompt_parts,
+    bool add_special,
+    bool parse_special_for_template_parts) {
+    if (!prompt_parts.is_array()) {
+        throw std::runtime_error("prompt_parts must be an array");
+    }
+
+    server_tokens result;
+    bool first = true;
+
+    for (const auto & part : prompt_parts) {
+        if (!part.is_object()) {
+            throw std::runtime_error("prompt_parts items must be objects");
+        }
+
+        std::string text = json_value(part, "text", std::string());
+        bool is_input = json_value(part, "is_input", false);
+
+        if (text.empty()) {
+            continue;
+        }
+
+        const bool parse_special = is_input ? false : parse_special_for_template_parts;
+        const bool add_special_now = first ? add_special : false;
+
+        auto tokens = common_tokenize(vocab, text, add_special_now, parse_special);
+        for (auto tok : tokens) {
+            result.push_back(tok);
+        }
+
+        first = false;
+    }
+
+    return result;
+}
